INSERT INTO events (slug, title, series, summary, body_md, starts_at, ends_at, timezone, venue, address, map_url, cover_key, registration_open, status) VALUES ('game-over-for-the-old-way-how-ai-reshapes-development', 'Game Over for the Old Way: How AI Reshapes Development', 'French Tech Talk', 'The gaming industry is booming — and we’re bringing together an incredible lineup of speakers from the French delegation for another inspiring panel discussion.', '🎮 The future of gaming is being written right here in Asia — and Bangkok is set to play a key role.

On the occasion of Gamescom Asia 2026, we’re excited to host the panel “Game Over for the Old Way: How AI reshapes Development”, bringing together a delegation of French entrepreneurs and startups to meet Thailand’s vibrant gaming community.

Thailand’s gaming market is on track to nearly double by 2030. This momentum makes the country one of the region’s most exciting playgrounds for developers, creators, and investors. By connecting French innovation with Thailand’s growth, we aim to spark new ideas, collaborations, and opportunities for the industry.

🙏 Huge thanks to the Ambassade de France en Thaïlande, Business France, and Institut Français for their incredible cooperation and support. ✨

Thank you to the Mercure Bangkok Surawong team for hosting us at the Starlight Rooftop Bar (indoor).

🎮 Join us and take part in the dialogue shaping the future of gaming — where innovation, culture, and technology meet. 🚀', 1793098800, 1793113200, 'Asia/Bangkok', 'Mercure Bangkok Surawong (R Floor)', 'Starlight Rooftop Bar, R Floor, 222 Surawong Rd, Khwaeng Si Phraya, Khet Bang Rak, Krung Thep Maha Nakhon 10500, Thailand', 'https://www.google.com/maps/search/?api=1&query=Mercure%20Bangkok%20Surawong%2C%20222%20Surawong%20Rd%2C%20Bangkok%2010500', 'events/game-over-for-the-old-way.jpg', 0, 'published') ON CONFLICT(slug) DO UPDATE SET title = excluded.title, series = excluded.series, summary = excluded.summary, body_md = excluded.body_md, starts_at = excluded.starts_at, ends_at = excluded.ends_at, timezone = excluded.timezone, venue = excluded.venue, address = excluded.address, map_url = excluded.map_url, cover_key = excluded.cover_key, registration_open = excluded.registration_open, status = excluded.status, updated_at = unixepoch();
